contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount, uint256 loanToCollateral) public payable {
        require(loanToCollateral >= 1);
        require(amount <= 1e30);
        require(loanToCollateral <= 1e30);

        uint256 firstID = c.requestLoan(amount, 0, loanToCollateral, 1); if (__ESBMC_reverted()) return;
        uint256 secondID = c.requestLoan(amount, 0, loanToCollateral, 1); if (__ESBMC_reverted()) return;

        assert(secondID > firstID);
    }
}

