pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 loanToCollateral) internal {
        vm.assume(loanToCollateral >= 1);
        vm.assume(amount <= 1e30);
        vm.assume(loanToCollateral <= 1e30);
        uint256 firstID;
        try c.requestLoan(amount, 0, loanToCollateral, 1) returns (uint256 __r) { firstID = __r; } catch { return; }
        uint256 secondID;
        try c.requestLoan(amount, 0, loanToCollateral, 1) returns (uint256 __r) { secondID = __r; } catch { return; }
        assertTrue(secondID > firstID);
    }

    function testFuzz_run(uint256 amount, uint256 loanToCollateral) public {
        _run(amount, loanToCollateral);
    }

    receive() external payable {}
}
